-- Vigilio LLMOps P0: single transactional baseline migration, forward-only.
CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL UNIQUE,display_name text NOT NULL,email_verified boolean NOT NULL DEFAULT false,disabled_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_credentials(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,password_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,csrf_hash text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,mfa_verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX user_sessions_user_exp_idx ON user_sessions(user_id,expires_at);
CREATE TABLE email_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,kind text NOT NULL CHECK(kind IN ('verify','reset')),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE social_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,provider text NOT NULL,subject text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider,subject));
CREATE TABLE oauth_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),state_hash text NOT NULL UNIQUE,cookie_hash text NOT NULL,return_to text NOT NULL,action text NOT NULL CHECK(action IN ('login','link')),initiating_user_id uuid REFERENCES users(id),expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mfa_factors(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,secret_ciphertext text NOT NULL,activated_at timestamptz,last_step bigint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE mfa_recovery_codes(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash text NOT NULL UNIQUE,used_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,code_hash));
CREATE TABLE consent_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,document_version text NOT NULL,consented_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deletion_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),identity_id uuid REFERENCES social_identities(id) ON DELETE SET NULL,confirmation_hash text NOT NULL UNIQUE,confirmation_ciphertext text NOT NULL,request_hash text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'queued',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,name text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','admin','developer','approver','analyst','viewer')),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,user_id));
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,slug text NOT NULL,name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,slug),UNIQUE(organization_id,id));
CREATE TABLE applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,environment text NOT NULL DEFAULT 'dev' CHECK(environment IN ('dev','staging','production')),archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,workspace_id) REFERENCES workspaces(organization_id,id));
CREATE TABLE application_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,prefix text NOT NULL,scopes text[] NOT NULL,expires_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE prompts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,description text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,name),FOREIGN KEY(organization_id,workspace_id) REFERENCES workspaces(organization_id,id));
CREATE TABLE prompt_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),prompt_id uuid NOT NULL REFERENCES prompts(id) ON DELETE CASCADE,version integer NOT NULL CHECK(version>=1),template text NOT NULL,model text NOT NULL,parameters jsonb NOT NULL DEFAULT '{}',sha256 text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(prompt_id,version));
CREATE TABLE datasets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,workspace_id) REFERENCES workspaces(organization_id,id));
CREATE TABLE dataset_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),dataset_id uuid NOT NULL REFERENCES datasets(id) ON DELETE CASCADE,input text NOT NULL,expected_output text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evaluation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),dataset_id uuid NOT NULL REFERENCES datasets(id),prompt_version_id uuid NOT NULL REFERENCES prompt_versions(id),status text NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','passed','failed','error')),score numeric(7,6),total_cases integer NOT NULL DEFAULT 0,passed_cases integer NOT NULL DEFAULT 0,error text,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,FOREIGN KEY(organization_id,workspace_id) REFERENCES workspaces(organization_id,id));
CREATE TABLE evaluation_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES evaluation_runs(id) ON DELETE CASCADE,case_id uuid NOT NULL REFERENCES dataset_cases(id),passed boolean NOT NULL,actual_output text NOT NULL,notes text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(run_id,case_id));
CREATE TABLE quality_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL,minimum_score numeric(7,6) NOT NULL CHECK(minimum_score BETWEEN 0 AND 1),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,workspace_id) REFERENCES workspaces(organization_id,id));
CREATE TABLE releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),prompt_version_id uuid NOT NULL REFERENCES prompt_versions(id),evaluation_run_id uuid NOT NULL REFERENCES evaluation_runs(id),policy_id uuid NOT NULL REFERENCES quality_policies(id),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','verified','approved','active','rolled_back','rejected')),created_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,workspace_id) REFERENCES workspaces(organization_id,id));
CREATE UNIQUE INDEX releases_workspace_one_active_idx ON releases(workspace_id) WHERE status='active';
CREATE TABLE traces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),workspace_id uuid NOT NULL REFERENCES workspaces(id),application_id uuid NOT NULL REFERENCES applications(id),trace_id text NOT NULL,model text NOT NULL,status text NOT NULL,latency_ms integer NOT NULL CHECK(latency_ms>=0),input_tokens integer NOT NULL DEFAULT 0 CHECK(input_tokens>=0),output_tokens integer NOT NULL DEFAULT 0 CHECK(output_tokens>=0),estimated_cost_usd numeric(14,8) NOT NULL DEFAULT 0,attributes jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id,trace_id));
CREATE INDEX traces_org_created_idx ON traces(organization_id,created_at DESC);
CREATE TABLE budget_policies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL UNIQUE REFERENCES organizations(id),limit_usd numeric(14,6) NOT NULL CHECK(limit_usd>=0),spent_usd numeric(14,6) NOT NULL DEFAULT 0 CHECK(spent_usd>=0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE budget_reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),idempotency_key text NOT NULL,estimated_usd numeric(14,6) NOT NULL,status text NOT NULL DEFAULT 'reserved',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,idempotency_key));
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic text NOT NULL,payload jsonb NOT NULL,published_at timestamptz,attempts integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending_idx ON outbox_events(created_at) WHERE published_at IS NULL;
CREATE TABLE processed_events(consumer text NOT NULL,event_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(consumer,event_id));
CREATE TABLE audit_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,organization_id uuid,actor_id uuid,action text NOT NULL,resource_type text NOT NULL,resource_id text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org_created_idx ON audit_events(organization_id,created_at DESC);
